changeSet.sql:
CREATE TABLE data_access_event ( id BIGSERIAL PRIMARY KEY, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), workspace_id BIGINT NOT NULL CONSTRAINT sfk_data_access_event_workspace_id REFERENCES workspace(id), actor_user_id BIGINT, subject_user_id BIGINT, resource_type VARCHAR(48) NOT NULL, CONSTRAINT ck_data_access_event_resource_type CHECK (resource_type IN ('PRACTICE_REPORT', 'PRACTICE_ROSTER')) );
-- Subject leads: "every disclosure about this person" is the GDPR Art. 15(1)(c) query shape, -- and the one an erasure request has to run. workspace_id follows so a per-workspace answer -- stays index-only. CREATE INDEX ix_data_access_event_subject ON data_access_event (subject_user_id, workspace_id, occurred_at DESC);
-- The mirror question: everything this actor disclosed. Serves the erasure UPDATE too. CREATE INDEX ix_data_access_event_actor ON data_access_event (actor_user_id, occurred_at DESC);
-- Workspace purge deletes by workspace_id; retention deletes by occurred_at. CREATE INDEX ix_data_access_event_workspace_occurred ON data_access_event (workspace_id, occurred_at DESC);

REVOKE UPDATE, TRUNCATE ON data_access_event FROM CURRENT_USER;

CREATE OR REPLACE FUNCTION data_access_event_block_mutation() RETURNS trigger AS $dae_immut$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF current_setting('hephaestus.audit_purge', true) = 'on' THEN
            RETURN OLD;
        END IF;
        IF OLD.occurred_at >= now() - interval '365 days' THEN
            RAISE EXCEPTION 'data_access_event is append-only: DELETE is permitted only past the 365-day retention window or during a workspace purge';
        END IF;
        RETURN OLD;
    END IF;

    IF (NEW.actor_user_id IS NULL OR NEW.actor_user_id = OLD.actor_user_id)
       AND (NEW.subject_user_id IS NULL OR NEW.subject_user_id = OLD.subject_user_id)
       AND (to_jsonb(NEW) - 'actor_user_id' - 'subject_user_id')
            IS NOT DISTINCT FROM (to_jsonb(OLD) - 'actor_user_id' - 'subject_user_id')
    THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'data_access_event is append-only: only erasure (setting actor or subject to NULL) is permitted';
END;
$dae_immut$ LANGUAGE plpgsql;

CREATE TRIGGER trg_data_access_event_block_mutation
    BEFORE UPDATE OR DELETE ON data_access_event
    FOR EACH ROW EXECUTE FUNCTION data_access_event_block_mutation();

CREATE OR REPLACE FUNCTION data_access_event_block_truncate() RETURNS trigger AS $dae_trunc$
BEGIN
    RAISE EXCEPTION 'data_access_event is append-only: TRUNCATE is not permitted';
END;
$dae_trunc$ LANGUAGE plpgsql;

CREATE TRIGGER trg_data_access_event_block_truncate
    BEFORE TRUNCATE ON data_access_event
    FOR EACH STATEMENT EXECUTE FUNCTION data_access_event_block_truncate();

rollback.sql:
DROP TRIGGER IF EXISTS trg_data_access_event_block_truncate ON data_access_event;
DROP TRIGGER IF EXISTS trg_data_access_event_block_mutation ON data_access_event;
DROP FUNCTION IF EXISTS data_access_event_block_truncate();
DROP FUNCTION IF EXISTS data_access_event_block_mutation();
GRANT UPDATE, TRUNCATE ON data_access_event TO CURRENT_USER;
